from lib import *
S = SS('x94')
steps = [
    step("基本用法:@EnableJpaAuditing(auditorAwareRef = \"auditor\"),实体上加 @EntityListeners(AuditingEntityListener.class) 和 @CreatedDate、@LastModifiedDate、@CreatedBy、@LastModifiedBy 四个字段,AuditorAware<String> 从一个 ThreadLocal 里取当前用户(这里用它代替 Spring Security)。alice 创建:save(new Doc) 之后创建时间 11:38:07.780801 by alice,修改时间和修改人是同一时刻同一个人;insert 语句是 insert into doc (created_by,created_date,last_modified_by,last_modified_date,title) values (?,?,?,?,?)。bob 在事务里改标题:发出的 update 是 update doc set last_modified_by=?,last_modified_date=?,title=? where id=?——不含 created_by 和 created_date(字段上写了 @Column(updatable = false)),改完之后创建时间和创建人没变,修改时间变成 11:38:08.925469、修改人 bob。", t=tl(S(1)), mark=lidx(S(1), 'SQL:update', 'bob 修改之后'), done=lidx(S(1), 'save(new Doc) 之后', 'SQL:insert'), b=bars([['insert 语句里的审计列个数(created_by、created_date、last_modified_by、last_modified_date)', 4, '4'], ['update 语句里的审计列个数(last_modified_by、last_modified_date)', 2, '2']], 4, done=[0], mark=[1]), kv=KV([['需要', '@EnableJpaAuditing + 实体 @EntityListeners + AuditorAware'], ['创建', '四个字段同时填上'], ['更新', '只改 last_modified_*,created_* 保持(updatable = false)'], ['当前用户', 'AuditorAware 提供']], ['需要'])),
    step("哪些情况不会更新 lastModifiedDate。把标题改成同样的值(脏检查发现没有变化,没有 update):修改时间和修改人都还是 bob 的 11:38:08.925469。只读取不修改:发出的 update 条数是 0。@Modifying 的批量 JPQL update 把标题改成「批量改」(carol 操作):标题变了,但修改时间仍是 11:38:08.925469、修改人仍是 bob——批量更新不经过实体生命周期回调,审计字段没有被碰。carol 用实体方式再改一次:修改时间 11:38:10.067201、修改人 carol。审计是挂在实体的回调上的,绕过实体的写法会漏掉。", t=tl(S(2)), mark=lidx(S(2), '@Modifying 批量'), done=lidx(S(2), '把标题改成同样的值', '只读取不修改', '实体方式再改一次'), b=bars([['同值修改后 lastModified 是否变化(0=没变)', 0, '没变'], ['只读取发出的 update 条数', 0, '0'], ['批量 update 后 lastModified 是否变化', 0, '没变(标题已变)'], ['实体方式再改后 lastModified 是否变化(1=变)', 1, '变了']], 1, mark=[2], done=[0, 1, 3]), kv=KV([['同值修改', '没有 update,审计字段不变'], ['只读取', '0 条 update'], ['批量 JPQL update', '标题变了,审计字段没变'], ['实体修改', '审计字段更新']], ['批量 JPQL update'])),
    step("AuditorAware 返回空、实体没有监听器。AuditorAware 返回 Optional.empty()(没有当前用户)时 save:创建时间和修改时间照常有值,createdBy 和 lastModifiedBy 是 null,不报错。如果实体上的注解齐全但忘了 @EntityListeners(AuditingEntityListener.class):createdDate=null、createdBy=null,什么都没填——光有 @EnableJpaAuditing 和注解不够,监听器要挂在实体上。", t=tl(S(3)), mark=lidx(S(3), '没有当前用户', '注解齐全'), done=[], b=bars([['没有当前用户时 createdDate 是否有值(1=有)', 1, '有'], ['没有当前用户时 createdBy 是否有值', 0, 'null'], ['没挂 @EntityListeners 时 createdDate 是否有值', 0, 'null']], 1, mark=[1, 2], done=[0]), kv=KV([['没有当前用户', '时间照填,人是 null,不报错'], ['没挂 @EntityListeners', '什么都不填'], ['静默', '两种情况都不报错'], ['建议', '把 createdBy 的列设成 not null 来暴露问题']], ['静默'])),
    step("换一个线程。AuditorAware 读的是 ThreadLocal:alice 的线程里提交任务,save 在线程池的线程里执行,结果 createdBy=null、lastModifiedBy=null。在任务内部先把用户设置到那个线程里(这里设成 carol)再 save,createdBy 和 lastModifiedBy 都是 carol。异步、线程池、响应式里用 ThreadLocal 取当前用户都要想清楚怎么传过去(Spring Security 的 SecurityContext 默认也是 ThreadLocal,同样不会自动带到新线程)。", t=tl(S(4)), mark=lidx(S(4), 'alice 的线程里调用'), done=lidx(S(4), '在任务里自己把用户设置'), b=bars([['另一个线程 save 后 createdBy 是否有值', 0, 'null'], ['先设置用户再 save 后 createdBy 是否有值', 1, 'carol']], 1, mark=[0], done=[1]), kv=KV([['ThreadLocal', '不会自动带到线程池的线程'], ['null', '另一个线程 save 的记录 createdBy 为空'], ['补救', '在任务里自己设置用户,或用能传递上下文的执行器'], ['未验证', 'Spring Security 的上下文传播(本篇用 ThreadLocal 代替)']], ['ThreadLocal'])),
    step("没有 @EnableJpaAuditing 会怎样。实体上有 @EntityListeners(AuditingEntityListener.class) 和四个注解,但没有 @EnableJpaAuditing:save 之后 创建时间 null、创建人 null、修改时间 null、修改人 null,也没有报错。注解、监听器、@EnableJpaAuditing 三个缺一个都会静默地不填。", t=tl(S(5)), mark=lidx(S(5), 'save 之后'), done=[], b=bars([['没开 @EnableJpaAuditing 时有值的审计字段个数', 0, '0'], ['开了之后有值的审计字段个数', 4, '4']], 4, mark=[0], done=[1]), kv=KV([['缺任意一个', '静默不填'], ['@EnableJpaAuditing', '开关,放在 @Configuration 上'], ['@EntityListeners', '放在实体上'], ['AuditorAware', '只管 createdBy / lastModifiedBy']], ['缺任意一个'])),
]
A = mkartx('x94', 94, 'Spring,Data,JPA,审计,Auditing,CreatedDate,真实验证,动画演示',
    '实测 Spring Data JPA 审计:@EnableJpaAuditing 加实体上的 @EntityListeners 与四个注解;更新时只改 last_modified_*;同值修改与只读不会更新审计字段,@Modifying 批量 update 会漏掉;AuditorAware 返回空时 createdBy 为 null 且不报错;换线程后 ThreadLocal 里的用户丢失;缺 @EnableJpaAuditing 或 @EntityListeners 都是静默不填。',
    '@CreatedDate 和 @LastModifiedBy 是怎么填上的?批量更新会不会更新修改时间?异步线程里用户怎么没了?忘了开 @EnableJpaAuditing 会报错吗?这篇在 Spring Boot 4.0.8、Hibernate 7、MySQL 上逐个实测。',
    [('2 个审计列', '更新时发出的 update 只含 last_modified_by 和 last_modified_date'), ('批量 update 不触发', '@Modifying 的 JPQL 更新之后,lastModified 与 lastModifiedBy 都没变'), ('createdBy = null', 'save 在另一个线程里执行时,AuditorAware 读不到 ThreadLocal 里的用户')],
    [('基本用法', '<p>@EnableJpaAuditing 加 @EntityListeners 加四个注解;更新只改 last_modified_*。</p>'),
     ('不触发的情况', '<p>同值修改、只读取和批量 JPQL 更新都不会更新审计字段。</p>'),
     ('静默失败', '<p>没有当前用户或缺监听器时审计字段为 null,不报错。</p>'),
     ('线程', '<p>AuditorAware 读 ThreadLocal,线程池里的 save 读不到用户。</p>'),
     ('开关', '<p>缺 @EnableJpaAuditing 也是静默不填。</p>')],
    steps,
    [ENV_X + '(Hibernate 7、Spring Data JPA 4 随 spring-boot-starter-data-jpa;MySQL 是本机自己起的 26.7.0 实例)。Doc 实体带四个审计字段(createdDate 与 createdBy 标了 updatable = false);AuditorAware<String> 从 ThreadLocal 取用户,代替 Spring Security;时间取自应用所在机器的时钟(LocalDateTime),不是数据库的;「没开 @EnableJpaAuditing」是另一次独立运行',
     '没有验证:真实的 Spring Security 下 AuditorAware 的写法与 SecurityContext 传播;Instant、OffsetDateTime 等其他时间类型;自定义 DateTimeProvider;@CreatedDate 在 MySQL 列精度(datetime 与 datetime(6))上的截断;Spring Data Envers 的历史审计;软删除与审计的配合'],
    '审计')
